#!/usr/bin/env python3
"""Bind final R9 full fit project, P02 reprint and focused CAD version evidence."""
from pathlib import Path
import hashlib,json
HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[3];CAD=HERE.parent;OUT=ROOT/'print/bambu-R9-palm-bracing-2026-10-25'
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
reports={n:json.loads((HERE/n).read_text()) for n in ['qa-project.json','qa-toolpaths.json','qa-palm-only-comparison.json']}
assert all(r['status'].startswith('PASS') for r in reports.values())
assert reports['qa-project.json']['failed_checks']==reports['qa-toolpaths.json']['failed_checks']==0
project=OUT/'Fingerworker_R9_H2D_04mm_PLA_Fit_Test.3mf';sliced=OUT/'validation/Fingerworker_R9_slice_verification.gcode.3mf';layout=OUT/'plate-layout.json'
assert reports['qa-project.json']['project_sha256']==reports['qa-toolpaths.json']['editable_project_sha256']==sha(project)
assert reports['qa-project.json']['layout_sha256']==reports['qa-toolpaths.json']['layout_sha256']==sha(layout)
assert reports['qa-toolpaths.json']['sliced_archive_sha256']==sha(sliced)
case=next(r for r in reports['qa-palm-only-comparison.json']['cases'] if 'wrist_down' in r['project']);secondary=Path(case['project']);secondary_slice=OUT/'validation/Fingerworker_R9_P02_wrist_down_H2D_04mm_PLA_verification.gcode.3mf';assert sha(secondary)==case['project_sha256'] and sha(secondary_slice)==case['sliced_archive_sha256']
native=json.loads((CAD/'validation-summary.json').read_text());assert native['status']=='NOMINAL_GEOMETRY_CHECKS_PASS' and native['failed_checks']==native['unresolved_checks']==0
assert reports['qa-project.json']['frozen_source_sha256']==reports['qa-toolpaths.json']['frozen_source_sha256']==native['source_sha256']
version=native['native_provenance']['immutable_version_id'];assert json.loads(layout.read_text())['native_R9_version']==version
prior_path=ROOT/'review/bambu-R8-fit-test-2026-10-24/qa-q01-fixture.json';prior=json.loads(prior_path.read_text());assert prior['status']=='PASS_UNLOADED_NOMINAL_FIXTURE_ASSEMBLY' and prior['failed_checks']==0 and prior['fixture_manifest_sha256']==sha(OUT/'fixture/manifest.json')
# Parent CAD audit bounds every added brace stock toX<=-22.75; Q01 startsX-20.5.
assert all(x['status']=='PASS' for x in json.loads((CAD/'palm-exact-audit.json').read_text())['checks'])
files=[project,sliced,secondary,secondary_slice,layout,OUT/'fixture/manifest.json',CAD/'validation-summary.json',prior_path,*[HERE/n for n in reports],*[HERE/n for n in ['audit_bambu_project.py','audit_bambu_toolpaths.py','audit_palm_prints.py','FIT_TEST_README.md','ASSEMBLY_DETAILS.md','PRINT_QA_NOTES.md']]]
result={'status':'PASS_PREPARED_R9_UNLOADED_FIT_PROJECT','failed_checks':0,'unresolved_checks':0,'independent_print_check_count':len(reports['qa-project.json']['checks'])+len(reports['qa-toolpaths.json']['checks'])+sum(len(x['checks']) for x in reports['qa-palm-only-comparison.json']['cases']),'scope':'Final full19-object and single-P02 wrist-down H2D0.4 PLA projects: native source triangles and scale1 proper transforms, settings/layout, actual positive extrusion/support paths, upper clean bearing faces and linked focused R9 native CAD identity. Unchanged Q01 geometry review inherited by exact fixture identity; added braces remain>=2.25mm axially clear.','immutable_version_id':version,'source_sha256':native['source_sha256'],'printer':'Bambu Lab H2D','nozzle_mm':.4,'filament':'PLA','bed':'Textured PEI Plate','full_plate_objects':19,'secondary_plate_objects':1,'palm_orientation':'NativeXmin wrist ledge down; bearing faces up, lid-gap underside vertical','new_brace_to_q01_minimum_axial_clearance_mm':2.25,'inherited_fixture_evidence':{'path':str(prior_path),'sha256':sha(prior_path),'checks':49,'scope':'Frozen R8 independent Q01 exact geometry/installation/p0motion; not rerun or relabeled as new R9 checks'},'files_sha256':{str(p.relative_to(ROOT)):sha(p) for p in files},'slicer_header':reports['qa-toolpaths.json']['header'],'secondary_slicer_header':case['header'],'limitations':['Unloaded gentle supported fit/motion only: Q01 has no axial latch; no springs/preload/isometric load/force/calibration test.','Both palm bearing pads must seat simultaneously without forcing palm screws; actual print flatness, tolerances, stiffness/creep and500N capacity are unqualified.','Hard PLA pad/rod proxies do not reproduce final material/friction/cushioning; real fasteners and matching heat-set inserts required.']}
(HERE/'qa-summary.json').write_text(json.dumps(result,indent=2)+'\n')
(HERE/'qa-summary.md').write_text('# R9 PLA print/assembly review\n\n**PASS** — '+str(result['independent_print_check_count'])+' independent print checks; zero failed/unresolved.\n\nFull19-piece unloaded-fit project plus single-P02 reprint, H2D0.4/PLA/texturedPEI/scale1. Final P02 prints wrist ledge down: both new bearing faces are upward top skin, with no adjacent support; the lid-gap face remains vertical. All actual object/support/brim paths are inside the shared bed and mutually separated. Native source triangles and proper rigid transforms are preserved; every object has a first model layer, and all four hard pad proxies finish at1.50mm.\n\nExact R9 CAD version and artifact hashes are bound in qa-summary.json. Physical simultaneous pad bearing, print cleanup, comfort, hardware fit and strength still require fitting; this is not a500N qualification. Q01 remains an unloaded p0-only fixture.\n')
print(result['status'],result['independent_print_check_count'],sha(HERE/'qa-summary.json'))
